begin;
alter table public.student_profiles enable row level security;
alter table public.tutor_profiles enable row level security;
alter table public.subscribers enable row level security;
drop policy if exists student_profiles_select_own_or_permitted on public.student_profiles;
create policy student_profiles_select_own_or_permitted on public.student_profiles for select to authenticated using (id=auth.uid() or private.has_permission('users','view') or private.has_permission('students','view'));
drop policy if exists student_profiles_insert_own on public.student_profiles;
create policy student_profiles_insert_own on public.student_profiles for insert to authenticated with check (id=auth.uid());
drop policy if exists student_profiles_update_own_or_permitted on public.student_profiles;
create policy student_profiles_update_own_or_permitted on public.student_profiles for update to authenticated using (id=auth.uid() or private.has_permission('users','edit') or private.has_permission('students','edit')) with check (id=auth.uid() or private.has_permission('users','edit') or private.has_permission('students','edit'));
drop policy if exists tutor_profiles_select_own_or_permitted on public.tutor_profiles;
create policy tutor_profiles_select_own_or_permitted on public.tutor_profiles for select to authenticated using (id=auth.uid() or private.has_permission('users','view') or private.has_permission('tutors','view'));
drop policy if exists tutor_profiles_insert_own on public.tutor_profiles;
create policy tutor_profiles_insert_own on public.tutor_profiles for insert to authenticated with check (id=auth.uid());
drop policy if exists tutor_profiles_update_own_or_permitted on public.tutor_profiles;
create policy tutor_profiles_update_own_or_permitted on public.tutor_profiles for update to authenticated using (id=auth.uid() or private.has_permission('users','edit') or private.has_permission('tutors','edit')) with check (id=auth.uid() or private.has_permission('users','edit') or private.has_permission('tutors','edit'));
drop policy if exists subscribers_select_own_or_finance on public.subscribers;
create policy subscribers_select_own_or_finance on public.subscribers for select to authenticated using (email=(select email from auth.users where id=auth.uid()) or private.has_permission('payments','view') or private.has_permission('finance','view'));
commit;
